static int
isPredefinedEntityName(const XML_Char *name, size_t nameLen) {
  switch (nameLen) {
  case 2:
    // Wanted: "lt" or "gt"
    if (name[1] != XML_T(ASCII_t))
      break;
    switch (name[0]) {
    case XML_T(ASCII_l):
