    break;
  case 3:
    // Wanted: "amp"
    if (name[0] == XML_T(ASCII_a) && name[1] == XML_T(ASCII_m)
        && name[2] == XML_T(ASCII_p))
      return ASCII_AMP;
    break;
  case 4:
    // Wanted: "apos" or "quot"
    switch (name[0]) {
    case XML_T(ASCII_a):
      if (name[1] == XML_T(ASCII_p) && name[2] == XML_T(ASCII_o)
          && name[3] == XML_T(ASCII_s))
        return ASCII_APOS;
      break;
    case XML_T(ASCII_q):
